        if(rd_mux_addr == 13'hd0) begin
            readback_data_var[31:0] = field_storage.SEP_REGION_SIZE.size.value;
        end
        if(rd_mux_addr == 13'h100) begin
            readback_data_var[55:0] = field_storage.SMU_GLOBAL_BASE_ADDR.addr.value;
        end
        if(rd_mux_addr == 13'h110) begin
            readback_data_var[31:0] = field_storage.SMU_REGION_SIZE.size.value;
