        if(rd_mux_addr == 13'h150) begin
            readback_data_var[0] = hwif_in.SEP_FUSE_SENSE_STATUS.sep_fuse_sense_done.next;
        end
        if(rd_mux_addr == 13'h178) begin
            readback_data_var[31:0] = field_storage.SEP_SW_DEBUG.sep_sw_debug.value;
        end
        if(rd_mux_addr == 13'h180) begin
            readback_data_var[0] = 1'h0;
            readback_data_var[31:1] = field_storage.SEP_NMI_VEC.nmi_vec.value;
        end
        if(rd_mux_addr == 13'h188) begin
            readback_data_var[0] = field_storage.SEP_NMI_VEC_LOCK.lock.value;
