        if(rd_mux_addr == 13'h1a8) begin
            readback_data_var[0] = hwif_in.DMA_BUS_ERR_STATUS.reg_path_err.next;
            readback_data_var[1] = hwif_in.DMA_BUS_ERR_STATUS.host_path_err.next;
